// Validate Asset Event
// output 1: valid event -> rule engine   output 2: invalid event -> Invalid Event
const assetList = flow.get("cfg_assets");
const system = flow.get("cfg_system");
const now = new Date().toISOString();

function invalid(code, reason) {
    msg.payload = { status: "INVALID", error_code: code, reason: reason,
                    topic: msg.topic, raw: msg.payload, timestamp: now };
    delete msg.error;
    return [null, msg];
}

if (!assetList || !system) return invalid("CONFIG_NOT_LOADED", "assets.json / system_config.json not loaded yet (check Config Error debug)");
const assets = Object.fromEntries(assetList.map(a => [a.id, a]));
const zones = system.hospital.zones;

if (msg.error) return invalid("MALFORMED_JSON", "Payload is not valid JSON");
const p = msg.payload;
if (p === null || p === undefined || typeof p !== "object" || Array.isArray(p))
    return invalid("EMPTY_OR_NOT_OBJECT", "Message is empty or not a JSON object");
if (typeof p.id !== "string" || p.id.trim() === "") return invalid("MISSING_ID", "Field 'id' is missing");
if (typeof p.room !== "string" || p.room.trim() === "") return invalid("MISSING_ROOM", "Field 'room' is missing");
if (!assets[p.id]) return invalid("UNKNOWN_ASSET", "Unknown asset: " + p.id);
if (!zones.includes(p.room)) return invalid("UNKNOWN_ZONE", "Unknown zone: " + p.room);

msg.asset = assets[p.id];
msg.event = { asset_id: p.id, room: p.room,
              timestamp: (typeof p.timestamp === "string" && p.timestamp) ? p.timestamp : now,
              source: (typeof p.source === "string" && p.source) ? p.source : "unknown" };
return [msg, null];

// Zone Violation Rule Engine (one generic engine for ALL assets)
// output 1: AUTHORIZED   output 2: VIOLATION
const asset = msg.asset, ev = msg.event;

// Runtime memory only (no database yet): { asset_id: {room, status, timestamp} }
const state = flow.get("asset_state") || {};
const prev = state[ev.asset_id] || null;

const authorized = asset.allowed_zones.includes(ev.room);
const status = authorized ? "AUTHORIZED" : "VIOLATION";
const wasViolation = !!prev && prev.status === "VIOLATION";

let violation_state;
if (status === "VIOLATION") violation_state = wasViolation ? "ONGOING" : "NEW";
else violation_state = wasViolation ? "CLEARED" : "NONE";

state[ev.asset_id] = { room: ev.room, status: status, timestamp: ev.timestamp };
flow.set("asset_state", state);

msg.payload = {
    asset_id: ev.asset_id,
    asset_type: asset.type,
    room: ev.room,
    previous_room: prev ? prev.room : null,
    allowed_zones: asset.allowed_zones,
    status: status,
    violation_state: violation_state,
    timestamp: ev.timestamp,
    source: ev.source,
    reason: authorized ? "Asset is authorized in this zone" : "Asset is not authorized in this zone"
};
delete msg.asset; delete msg.event;
return authorized ? [msg, null] : [null, msg];

// Set Config Paths
// Uses env var ASSET_TRACKER_CONFIG_DIR if set, otherwise EDIT THE PATH BELOW
// (use forward slashes, e.g. "C:/Users/you/asset-tracking-system/config")
const CONFIG_DIR = env.get("ASSET_TRACKER_CONFIG_DIR") || "C:/Users/nallu/Downloads/asset-tracking-system/config";
const a = { filename: CONFIG_DIR + "/assets.json",        cfgkey: "assets" };
const s = { filename: CONFIG_DIR + "/system_config.json", cfgkey: "system" };
return [[a, s]];

// Store Config -> flow context (single source of truth = config/*.json)
let data = msg.payload;
if (msg.cfgkey === "assets") {
    data = Array.isArray(data) ? data : (data && data.assets);
    if (!Array.isArray(data)) { node.error("assets.json must contain an 'assets' array", msg); return null; }
} else if (!(data && data.hospital && Array.isArray(data.hospital.zones))) {
    node.error("system_config.json must contain hospital.zones", msg); return null;
}
flow.set("cfg_" + msg.cfgkey, data);
const n = msg.cfgkey === "assets" ? data.length + " assets" : data.hospital.zones.length + " zones";
node.status({ fill: "green", shape: "dot", text: msg.cfgkey + ": " + n });
msg.payload = { config: msg.cfgkey, loaded: true, detail: n, from: msg.filename };
return msg;

// Build Init SQL: idempotent (IF NOT EXISTS) - never drops or deletes data
flow.set("db_ready", false);
msg.topic = `CREATE TABLE IF NOT EXISTS asset_events (
    id              INTEGER PRIMARY KEY AUTOINCREMENT,
    asset_id        TEXT NOT NULL,
    asset_type      TEXT,
    room            TEXT NOT NULL,
    previous_room   TEXT,
    status          TEXT NOT NULL,
    violation_state TEXT NOT NULL,
    timestamp       TEXT NOT NULL,
    source          TEXT,
    reason          TEXT,
    allowed_zones   TEXT,
    created_at      TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_asset_events_asset_id  ON asset_events(asset_id);
CREATE INDEX IF NOT EXISTS idx_asset_events_timestamp ON asset_events(timestamp);
CREATE INDEX IF NOT EXISTS idx_asset_events_status    ON asset_events(status);
CREATE INDEX IF NOT EXISTS idx_asset_events_room      ON asset_events(room);`;
return msg;

// Mark DB Ready (runs only after the schema statements succeeded)
flow.set("db_ready", true);
node.status({ fill: "green", shape: "dot", text: "database ready" });
msg.payload = { database: "asset_tracking.db", table: "asset_events", status: "initialized (existing data kept)" };
return msg;

// Prepare DB Insert: maps the Phase 2 standardized event to a parameterized INSERT
const e = msg.payload;
if (!flow.get("db_ready")) { node.error("Database not initialized yet - event NOT saved", msg); return null; }
const req = ["asset_id", "room", "status", "violation_state", "timestamp"];
const missing = req.filter(k => typeof e[k] !== "string" || e[k] === "");
if (missing.length) { node.error("Cannot save event, missing field(s): " + missing.join(", "), msg); return null; }

msg.event_saved = { asset_id: e.asset_id, room: e.room, status: e.status, violation_state: e.violation_state };
// order must match the ? placeholders in the SQLite - Insert Event node
msg.params = [
    e.asset_id, e.asset_type ?? null, e.room, e.previous_room ?? null, e.status,
    e.violation_state, e.timestamp, e.source ?? null, e.reason ?? null,
    JSON.stringify(e.allowed_zones ?? [])
];
return msg;

// Format Insert Success
msg.payload = Object.assign({ rows_written: 1 }, msg.event_saved);
node.status({ fill: "green", shape: "dot", text: msg.event_saved.asset_id + " -> " + msg.event_saved.room });
return msg;

// Format DB Error: show the real database error
const src = msg.error && msg.error.source ? msg.error.source.name : "unknown node";
msg.payload = { database_error: msg.error ? msg.error.message : "unknown error", failed_in: src,
                event: msg.event_saved || null };
return msg;
